// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter, IVaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    MockAC ac;
    address clone;

    function setUp() public {
        c = new VaultAdapter(); // constructor disables initializers, so use a clone (fresh storage, no constructor)
        ac = new MockAC();
        clone = _clone();
    }

    function _clone() internal returns (address a) {
        bytes memory rt = address(c).code;
        bytes memory init = abi.encodePacked(hex"61", uint16(rt.length), hex"80600c6000396000f3", rt);
        assembly {
            a := create(0, add(init, 0x20), mload(init))
        }
    }

    function testFuzz_property(address caller, address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(caller != address(0));
        vm.assume(asset != address(0));
        kink = bound(kink, 1, 1e27 - 1);
        slope0 = bound(slope0, 0, 1e18);
        slope1 = bound(slope1, 0, 1e18);

        bool initOk;
        try VaultAdapter(clone).initialize(address(ac)) {
            initOk = true;
        } catch {
            initOk = false;
        }
        assertTrue(initOk, "initialize must succeed on a fresh initializable instance");

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        vm.prank(caller);
        bool ok;
        try VaultAdapter(clone).setSlopes(asset, slopes) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "after initialize with a granting access control, setSlopes must succeed");
    }
}

contract MockAC {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}
